1605: /// .NET ticks (100 ns since 0001-01-01 UTC) of an ISO time, `""` when it does not parse.
1606: fn utc_ticks(iso: &str) -> String {
1607:     match DateTime::parse_from_rfc3339(iso.trim()) {
1608:         Ok(d) => {
1609:             let d = d.with_timezone(&Utc);
