1612:                 + d.timestamp() as i128 * 10_000_000
1613:                 + (d.timestamp_subsec_nanos() / 100) as i128;
1614:             t.to_string()
1615:         }
1616:         Err(_) => String::new(),
1617:     }
1618: }
